"""Self-checks for the kinematics in MyRobot.py. No robot needed.

Run: python test_kinematics.py
"""
import random
from MyRobot import forward_kinematics as fk, inverse_kinematics as ik, jacobian, cosd, sind
import math

# Hand-calculated example: tool point (110, 63.5, 34) mm, link 4 pointing straight down
assert all(abs(a - b) < 0.1 for a, b in zip(ik(0.110, 0.0635, 0.034, -90), (30, -30, -90, -60)))

# Round trip FK(IK(p)) = p, using targets generated by FK of random elbow-up poses
random.seed(0)
for _ in range(1000):
    q = (random.uniform(-90, 90), random.uniform(-90, 90), random.uniform(-170, -5), random.uniform(-90, 90))
    p = fk(*q)
    # IK only handles targets in front of the base axis (r >= 0), so skip poses that reach back
    if p[0] * cosd(q[0]) + p[1] * sind(q[0]) < 0:
        continue
    assert all(abs(a - b) < 1e-6 for a, b in zip(fk(*ik(*p)), p)), (q, p)

# Unreachable targets must raise instead of producing joint angles
try:
    ik(1.0, 0, 0, 0)
    raise AssertionError("unreachable target was accepted")
except ValueError:
    pass


# Jacobian vs. finite differences of FK
def in_arm_plane(q, base):
    """Tool pose as (tangential, radial, vertical, pitch [rad]) in the vertical plane at base angle `base`."""
    x, y, z, pitch = fk(*q)
    return (-x * sind(base) + y * cosd(base), x * cosd(base) + y * sind(base), z, math.radians(pitch))


h = 1e-4  # step [deg]
for _ in range(200):
    q = [random.uniform(-90, 90) for _ in range(4)]
    J = jacobian(*q)
    for col in range(4):
        q_step = list(q); q_step[col] += h
        numeric = [(b - a) / math.radians(h) for a, b in zip(in_arm_plane(q, q[0]), in_arm_plane(q_step, q[0]))]
        assert all(abs(J[row, col] - numeric[row]) < 1e-4 for row in range(4)), (q, col)

print("all kinematics checks passed")
